(window.WPF_FRAGMENTS = window.WPF_FRAGMENTS || {})["whats-new"] = {"source":"admin-entry-detail--pdf","html":"<template data-snap-fragment=\"modal-whats-new\" data-snap-source=\"jquery-confirm dialog (wpforms/assets/lib/jquery.confirm/jquery-confirm.min.js)\"><div class=\"jconfirm jconfirm-modern jconfirm-open\" style=\"bottom: 0px;\"><div class=\"jconfirm-bg\" style=\"transition-duration: 0.4s; transition-timing-function: cubic-bezier(0.36, 0.55, 0.19, 1);\"></div><div class=\"jconfirm-scrollpane\"><div class=\"jconfirm-row\"><div class=\"jconfirm-cell\"><div class=\"jconfirm-holder\" style=\"padding-top: 50px; padding-bottom: 50px;\"><div class=\"jc-bs3-container\"><div class=\"jc-bs3-row\"><div class=\"jconfirm-box-container jconfirm-animated jconfirm-no-transition\" style=\"transform: none; transition-duration: 0.4s; transition-timing-function: cubic-bezier(0.36, 0.55, 0.19, 1); padding-top: 50px; opacity: 1;\"><div class=\"jconfirm-box jconfirm-hilight-shake jconfirm-type-default jconfirm-type-animated\" role=\"dialog\" aria-labelledby=\"jconfirm-box42633\" tabindex=\"-1\" style=\"max-width: 1000px; transition-duration: 0.4s; transition-timing-function: cubic-bezier(0.36, 0.55, 0.19, 1); transition-property: all, margin;\"><div class=\"jconfirm-closeIcon\" style=\"display: block;\">×</div><div class=\"jconfirm-title-c\" style=\"display: none;\"><span class=\"jconfirm-icon-c\"></span><span class=\"jconfirm-title\"></span></div><div class=\"jconfirm-content-pane\" style=\"transition-duration: 0.4s; transition-timing-function: cubic-bezier(0.36, 0.55, 0.19, 1); max-height: 800px;\"><div class=\"jconfirm-content\" id=\"jconfirm-box42633\"><div>\n\t<div id=\"wpforms-splash-modal\">\n\t\t<header>\n\t<img src=\"../_shared/lib/site/wp-content/plugins/wpforms/assets/images/splash/sullie.svg\" alt=\"\">\n\t<div class=\"wpforms-splash-header-content\">\n\t\t<h2>\n\t\t\tWhat’s New in WPForms\t\t</h2>\n\t\t<p>We've added some great new features to help grow your business and generate more leads. Here are the highlights...</p>\n\t</div>\n</header>\n\t\t\t\t<main>\n\t\t\t\n<section class=\"wpforms-splash-section wpforms-splash-section-fifty-fifty\">\n\t<div class=\"wpforms-splash-section-content\">\n\t\t\t\t<h3>Create QR Codes Without Leaving the Form Builder</h3>\n\t\t<p>Point one at a page on your site or any custom URL. Drop your logo in the center so it looks like it belongs to your brand and download it for flyers, packaging, or event signage. No third-party tools, no code required.</p>\n\n\t\t\t\t\t<div class=\"wpforms-splash-section-buttons\">\n\t\t\t\t<a href=\"https://wpforms.com/docs/creating-a-qr-code-for-your-form/?utm_source=WordPress&amp;utm_campaign=plugin&amp;utm_medium=Whats%20New%20Splash&amp;utm_content=QR%20Code%20Try%20It%20Out%20BasicPlusProElite\" class=\"wpforms-btn wpforms-btn-orange\" target=\"_blank\" rel=\"noopener noreferrer\">Try It Out</a><a href=\"https://wpforms.com/introducing-wpforms-qr-code/?utm_source=WordPress&amp;utm_campaign=plugin&amp;utm_medium=Whats%20New%20Splash&amp;utm_content=QR%20Code%20Learn%20More%20BasicPlusProElite\" class=\"wpforms-btn wpforms-btn-bordered\" target=\"_blank\" rel=\"noopener noreferrer\">Learn More</a>\t\t\t</div>\n\t\t\t</div>\n\n\t\t\t<div class=\"wpforms-splash-section-image wpforms-image-shadow-no\">\n\t\t\t<img src=\"../_shared/assets/1c33b4306829.png\" alt=\"\">\n\t\t</div>\n\t</section>\n\n<section class=\"wpforms-splash-section wpforms-splash-section-fifty-fifty\">\n\t<div class=\"wpforms-splash-section-content\">\n\t\t\t\t<h3>Prioritize Responses With the Ranking Field</h3>\n\t\t<p>Instead of asking people to score each option separately, the Ranking field asks them to drag options into the order they prefer. This is the difference between knowing someone&nbsp;likes&nbsp;your ideas and knowing which one they want&nbsp;first.</p>\n\n\t\t\t\t\t<div class=\"wpforms-splash-section-buttons\">\n\t\t\t\t<a href=\"https://wpforms.com/docs/ranking-field/?utm_source=WordPress&amp;utm_campaign=plugin&amp;utm_medium=Whats%20New%20Splash&amp;utm_content=Ranking%20Field%20Try%20It%20Out%20ProElite\" class=\"wpforms-btn wpforms-btn-orange\" target=\"_blank\" rel=\"noopener noreferrer\">Try It Out</a><a href=\"https://wpforms.com/introducing-wpforms-ranking-field/?utm_source=WordPress&amp;utm_campaign=plugin&amp;utm_medium=Whats%20New%20Splash&amp;utm_content=Ranking%20Field%20Learn%20More%20ProElite\" class=\"wpforms-btn wpforms-btn-bordered\" target=\"_blank\" rel=\"noopener noreferrer\">Learn More</a>\t\t\t</div>\n\t\t\t</div>\n\n\t\t\t<div class=\"wpforms-splash-section-image wpforms-image-shadow-no\">\n\t\t\t<img src=\"../_shared/assets/bef691417bda.png\" alt=\"\">\n\t\t</div>\n\t</section>\n\n<section class=\"wpforms-splash-section wpforms-splash-section-full-width\">\n\t<div class=\"wpforms-splash-section-content\">\n\t\t\t\t<h3>Built-In Form Performance Tracking</h3>\n\t\t<p><span data-sheets-root=\"1\">Turn form data into better results with WPForms Analytics. Monitor conversions, identify friction points, and get AI-powered insights to improve your forms.</span></p>\n\n\t\t\t\t\t<div class=\"wpforms-splash-section-buttons\">\n\t\t\t\t<a href=\"https://sulliesbakery.com/wp-admin/admin.php?page=wpforms-overview\" class=\"wpforms-btn wpforms-btn-orange\" target=\"_blank\" rel=\"noopener noreferrer\">Try it Out</a><a href=\"https://wpforms.com/introducing-wpforms-analytics/?utm_source=WordPress&amp;utm_campaign=plugin&amp;utm_medium=Whats%20New%20Splash&amp;utm_content=Analytics%20Learn%20More%20ProElite\" class=\"wpforms-btn wpforms-btn-bordered\" target=\"_blank\" rel=\"noopener noreferrer\">Learn More</a>\t\t\t</div>\n\t\t\t</div>\n\n\t\t\t<div class=\"wpforms-splash-section-image wpforms-image-shadow-none\">\n\t\t\t<img src=\"../_shared/assets/bb689eacf1b2.png\" alt=\"\">\n\t\t</div>\n\t</section>\n\n<section class=\"wpforms-splash-section wpforms-splash-section-fifty-fifty\">\n\t<div class=\"wpforms-splash-section-content\">\n\t\t\t\t<h3>Build and Edit Forms with Your Favorite AI Assistant</h3>\n\t\t<p><span data-sheets-root=\"1\">The assistant you already use out in the world can now reach in and build forms for you, thanks to write support in the WordPress Abilities API.</span></p>\n\n\t\t\t\t\t<div class=\"wpforms-splash-section-buttons\">\n\t\t\t\t<a href=\"https://sulliesbakery.com/wp-admin/admin.php?page=wpforms-tools&amp;view=ai-mcp\" class=\"wpforms-btn wpforms-btn-orange\" target=\"_blank\" rel=\"noopener noreferrer\">Try it Out</a><a href=\"https://wpforms.com/announcing-write-support-abilities-api/?utm_source=WordPress&amp;utm_campaign=liteplugin&amp;utm_medium=Whats%20New%20Splash&amp;utm_content=AI%20Assistant%20Learn%20More%20Lite\" class=\"wpforms-btn wpforms-btn-bordered\" target=\"_blank\" rel=\"noopener noreferrer\">Learn More</a>\t\t\t</div>\n\t\t\t</div>\n\n\t\t\t<div class=\"wpforms-splash-section-image wpforms-image-shadow-no\">\n\t\t\t<img src=\"../_shared/assets/5f31a44d86e9.png\" alt=\"\">\n\t\t</div>\n\t</section>\n\n<section class=\"wpforms-splash-section wpforms-splash-section-fifty-fifty\">\n\t<div class=\"wpforms-splash-section-content\">\n\t\t\t\t<h3>Entry Importer: Save Time on Form Migrations</h3>\n\t\t<p><span data-sheets-root=\"1\">Entry Importer lets you bring your actual form submissions into WPForms from virtually any source. Your forms are here. Now your data can be too. Import from any CSV file, or migrate directly from other WordPress form plugins.</span></p>\n\n\t\t\t\t\t<div class=\"wpforms-splash-section-buttons\">\n\t\t\t\t<a href=\"https://sulliesbakery.com/wp-admin/admin.php?page=wpforms-tools\" class=\"wpforms-btn wpforms-btn-orange\" target=\"_blank\" rel=\"noopener noreferrer\">Try It Out</a><a href=\"https://wpforms.com/introducing-wpforms-v1-10-1/?utm_source=WordPress&amp;utm_campaign=plugin&amp;utm_medium=Whats%20New%20Splash&amp;utm_content=Entry%20Importer%20Learn%20More%20BasicPlusProElite\" class=\"wpforms-btn wpforms-btn-bordered\" target=\"_blank\" rel=\"noopener noreferrer\">Learn More</a>\t\t\t</div>\n\t\t\t</div>\n\n\t\t\t<div class=\"wpforms-splash-section-image wpforms-image-shadow-no\">\n\t\t\t<img src=\"../_shared/assets/acb3e80b6469.png\" alt=\"\">\n\t\t</div>\n\t</section>\n\n<section class=\"wpforms-splash-section wpforms-splash-section-fifty-fifty\">\n\t<div class=\"wpforms-splash-section-content\">\n\t\t\t\t<h3>Smart Edit With AI</h3>\n\t\t<p><span data-sheets-root=\"1\">Now you can edit any existing form using plain, conversational language from a chat box right inside the form builder. Add, remove, and reorder fields. Update field properties and form settings. Build and modify conditional logic. Configure email notifications, and more!</span></p>\n\n\t\t\t\t\t<div class=\"wpforms-splash-section-buttons\">\n\t\t\t\t<a href=\"https://wpforms.com/docs/editing-forms-with-wpforms-ai/?utm_source=WordPress&amp;utm_campaign=plugin&amp;utm_medium=Whats%20New%20Splash&amp;utm_content=Smart%20Edit%20With%20AI%20Try%20It%20Out%20BasicPlusProElite\" class=\"wpforms-btn wpforms-btn-orange\" target=\"_blank\" rel=\"noopener noreferrer\">Try It Out</a><a href=\"https://wpforms.com/introducing-wpforms-v1-10-1/?utm_source=WordPress&amp;utm_campaign=plugin&amp;utm_medium=Whats%20New%20Splash&amp;utm_content=Smart%20Edit%20With%20AI%20Learn%20More%20BasicPlusProElite\" class=\"wpforms-btn wpforms-btn-bordered\" target=\"_blank\" rel=\"noopener noreferrer\">Learn More</a>\t\t\t</div>\n\t\t\t</div>\n\n\t\t\t<div class=\"wpforms-splash-section-image wpforms-image-shadow-no\">\n\t\t\t<img src=\"../_shared/assets/818fd3118806.png\" alt=\"\">\n\t\t</div>\n\t</section>\n\n<section class=\"wpforms-splash-section wpforms-splash-section-full-width\">\n\t<div class=\"wpforms-splash-section-content\">\n\t\t\t\t<h3>Improved Surveys &amp; Polls Reports</h3>\n\t\t<p><span data-sheets-root=\"1\">Completely redesigned, the Surveys &amp; Polls reporting now features an advanced filter system with saveable presets, customizable graph styles for a personalized view, and multiple export options alongside tailored print layouts.</span></p>\n\n\t\t\t\t\t<div class=\"wpforms-splash-section-buttons\">\n\t\t\t\t<a href=\"https://sulliesbakery.com/wp-admin/admin.php?page=wpforms-addons\" class=\"wpforms-btn wpforms-btn-orange\" target=\"_blank\" rel=\"noopener noreferrer\">Try It Out</a><a href=\"https://wpforms.com/announcing-surveys-polls-reimagined-reporting/?utm_source=WordPress&amp;utm_campaign=plugin&amp;utm_medium=Whats%20New%20Splash&amp;utm_content=Improved%20Surveys%20&amp;%20Polls%20Reports%20Learn%20More%20ProElite\" class=\"wpforms-btn wpforms-btn-bordered\" target=\"_blank\" rel=\"noopener noreferrer\">Learn More</a>\t\t\t</div>\n\t\t\t</div>\n\n\t\t\t<div class=\"wpforms-splash-section-image wpforms-image-shadow-none\">\n\t\t\t<img src=\"../_shared/assets/acabe92cc4eb.png\" alt=\"\">\n\t\t</div>\n\t</section>\n\n<section class=\"wpforms-splash-section wpforms-splash-section-one-third-two-thirds\">\n\t<div class=\"wpforms-splash-section-content\">\n\t\t\t\t<h3>More Ways to Pay, More Reasons to Stay: PayPal for All</h3>\n\t\t<p><span data-sheets-root=\"1\">PayPal is now available to everyone, with an expanded integration that adds Pay Later, Google Pay, Apple Pay, Venmo, Fastlane accelerated checkout, and regional payment methods alongside standard PayPal and card payments.</span></p>\n\n\t\t\t\t\t<div class=\"wpforms-splash-section-buttons\">\n\t\t\t\t<a href=\"https://sulliesbakery.com/wp-admin/admin.php?page=wpforms-addons\" class=\"wpforms-btn wpforms-btn-orange\" target=\"_blank\" rel=\"noopener noreferrer\">Try It Out</a><a href=\"https://wpforms.com/announcing-paypal-for-all-users/?utm_source=WordPress&amp;utm_campaign=plugin&amp;utm_medium=Whats%20New%20Splash&amp;utm_content=PayPal%20for%20All%20Learn%20More%20BasicPlusProElite\" class=\"wpforms-btn wpforms-btn-bordered\" target=\"_blank\" rel=\"noopener noreferrer\">Learn More</a>\t\t\t</div>\n\t\t\t</div>\n\n\t\t\t<div class=\"wpforms-splash-section-image wpforms-image-shadow-none\">\n\t\t\t<img src=\"../_shared/assets/9ad55dd55de4.png\" alt=\"\">\n\t\t</div>\n\t</section>\n\n<section class=\"wpforms-splash-section wpforms-splash-section-fifty-fifty\">\n\t<div class=\"wpforms-splash-section-content\">\n\t\t\t\t<h3>Drop a Pin With the Map Field</h3>\n\t\t<p><span data-sheets-root=\"1\">Give visitors a better way to choose a location. The Map field embeds an interactive map directly in your form, with pins for each of your locations. Visitors can browse the map, click pins for details, and select a location, all without leaving the form.</span></p>\n\n\t\t\t\t\t<div class=\"wpforms-splash-section-buttons\">\n\t\t\t\t<a href=\"https://wpforms.com/docs/using-the-map-field/?utm_source=WordPress&amp;utm_campaign=plugin&amp;utm_medium=Whats%20New%20Splash&amp;utm_content=Map%20Field%20Try%20It%20Out%20ProElite\" class=\"wpforms-btn wpforms-btn-orange\" target=\"_blank\" rel=\"noopener noreferrer\">Try It Out</a><a href=\"https://wpforms.com/announcing-map-field/?utm_source=WordPress&amp;utm_campaign=plugin&amp;utm_medium=Whats%20New%20Splash&amp;utm_content=Map%20Field%20Learn%20More%20ProElite\" class=\"wpforms-btn wpforms-btn-bordered\" target=\"_blank\" rel=\"noopener noreferrer\">Learn More</a>\t\t\t</div>\n\t\t\t</div>\n\n\t\t\t<div class=\"wpforms-splash-section-image wpforms-image-shadow-no\">\n\t\t\t<img src=\"../_shared/assets/066cbe388ac2.png\" alt=\"\">\n\t\t</div>\n\t</section>\n\n<section class=\"wpforms-splash-section wpforms-splash-section-full-width\">\n\t<div class=\"wpforms-splash-section-content\">\n\t\t\t\t<h3>Build Engaging Quizzes in Seconds</h3>\n\t\t<p><span data-sheets-root=\"1\">Generate complete quizzes with conditional logic using simple prompts. Start from scratch or choose from 50+ quiz templates designed to engage your audience. Building powerful quizzes has never been easier.</span></p>\n\n\t\t\t\t\t<div class=\"wpforms-splash-section-buttons\">\n\t\t\t\t<a href=\"https://sulliesbakery.com/wp-admin/admin.php?page=wpforms-addons\" class=\"wpforms-btn wpforms-btn-orange\" target=\"_blank\" rel=\"noopener noreferrer\">Try It Out</a><a href=\"https://wpforms.com/announcing-quiz-addon/?utm_source=WordPress&amp;utm_campaign=plugin&amp;utm_medium=Whats%20New%20Splash&amp;utm_content=Quiz%20Addon%20Learn%20More%20ProElite\" class=\"wpforms-btn wpforms-btn-bordered\" target=\"_blank\" rel=\"noopener noreferrer\">Learn More</a>\t\t\t</div>\n\t\t\t</div>\n\n\t\t\t<div class=\"wpforms-splash-section-image wpforms-image-shadow-none\">\n\t\t\t<img src=\"../_shared/assets/7272885dea87.png\" alt=\"\">\n\t\t</div>\n\t</section>\n\t\t</main>\n\t\t\t</div>\n</div></div></div><div class=\"jconfirm-buttons\" style=\"display: none;\"></div><div class=\"jconfirm-clear\"></div></div></div></div></div></div></div></div></div></div></template>"};
